<?php
/** Catálogo de páginas no padrão de extensões: tabela responsiva, ações acessíveis e remoção recuperável revisionada. */
declare(strict_types=1);
use function DBLESSCMS\e;
use DBLESSCMS\{Icons,PagePublications};
$homepageRegistry=new \DBLESSCMS\Plugins($context->store);$homepageEnabled=isset($homepageRegistry->all()['homepage'])&&$homepageRegistry->state('homepage')['enabled'];
$publicationReader=new PagePublications($context->store);$catalog=$publicationReader->read();$siteRevision=$context->store->read('site')['revision'];
foreach(['search','status','sort','direction','catalog_page','display'] as $parameter)if(isset($_GET[$parameter])&&!is_string($_GET[$parameter]))throw new \DBLESSCMS\HttpError(422,'Invalid catalog query.','pages.editorial.invalid');
$search=substr($_GET['search']??'',0,120);$filter=$_GET['status']??'';$sort=$_GET['sort']??'title';$direction=($_GET['direction']??'asc')==='desc'?-1:1;$display=($_GET['display']??'list')==='tree'?'tree':'list';$rows=[];
foreach($pages as $id=>$item){$row=$catalog['data']['records'][$id]??null;$item['state']=$row===null?$item['data']['status']:PagePublications::status($row);$item['updated']=$row['updatedAt']??'';$item['publishedAt']=$row['publishAt']??'';$item['model']=$row['model']??'legacy';$item['title']=$row['draft']['document']['meta']['title']??$item['data']['meta']['title'];$item['depth']=0;$parent=$row['parent']??'';$lineage=[];while($parent!==''&&$item['depth']<12&&!in_array($parent,$lineage,true)){$lineage[]=$parent;$item['depth']++;$parent=$catalog['data']['records'][$parent]['parent']??'';}$item['treeKey']=implode('/',[...array_reverse($lineage),(string)$id]);if(($filter!==''&&$item['state']!==$filter)||($search!==''&&stripos($item['title'].' '.$id,$search)===false))continue;$rows[$id]=$item;}
$sort=in_array($sort,['title','updated','publishedAt','state'],true)?$sort:'title';uasort($rows,static fn(array $a,array $b):int=>$display==='tree'?strcmp($a['treeKey'],$b['treeKey']):($direction*strnatcasecmp($a[$sort],$b[$sort])));
$pageSize=$context->settings['browser']['pageSize']??25;$total=count($rows);$pageCount=max(1,(int)ceil($total/$pageSize));$catalogPage=min($pageCount,max(1,(int)($_GET['catalog_page']??1)));$rows=array_slice($rows,($catalogPage-1)*$pageSize,$pageSize,true);
/** Build same-route pagination links from validated local filter values; receives page, returns escaped-at-use URL without mutation. */
$pageLink=static fn(int $number):string=>$context->base.'/cms-admin/?'.http_build_query(['view'=>'plugin-panel','plugin'=>'pages','route'=>'overview','search'=>$search,'status'=>$filter,'sort'=>$sort,'direction'=>$direction===1?'asc':'desc','display'=>$display,'catalog_page'=>$number]);
?>
<section class="panel">
<form method="get" class="field-grid"><input type="hidden" name="view" value="plugin-panel"><input type="hidden" name="plugin" value="pages"><input type="hidden" name="route" value="overview"><label><?= e($t('pages.search')) ?><input name="search" value="<?= e($search) ?>" type="search" maxlength="120"></label><label><?= e($t('pages.filter')) ?><select name="status"><option value=""><?= e($t('pages.all')) ?></option><?php foreach(['draft','published','modified','scheduled'] as $state): ?><option value="<?= e($state) ?>" <?= $filter===$state?'selected':'' ?>><?= e($t('pages.state.'.$state)) ?></option><?php endforeach; ?></select></label><label><?= e($t('pages.sort')) ?><select name="sort"><?php foreach(['title'=>'pages.editorialTitle','updated'=>'pages.updated','publishedAt'=>'pages.publishedAt','state'=>'pages.filter'] as $value=>$label): ?><option value="<?= e($value) ?>" <?= $sort===$value?'selected':'' ?>><?= e($t($label)) ?></option><?php endforeach; ?></select></label><select name="direction" aria-label="<?= e($t('pages.sort')) ?>"><option value="asc" <?= $direction===1?'selected':'' ?>>↑</option><option value="desc" <?= $direction===-1?'selected':'' ?>>↓</option></select><label><?= e($t('pages.catalogView')) ?><select name="display"><option value="list" <?= $display==='list'?'selected':'' ?>><?= e($t('pages.flat')) ?></option><option value="tree" <?= $display==='tree'?'selected':'' ?>><?= e($t('pages.hierarchy')) ?></option></select></label><button type="submit" class="icon-button" title="<?= e($t('pages.search')) ?>" aria-label="<?= e($t('pages.search')) ?>"><?= Icons::svg('refresh',$context->base) ?></button></form>
<div class="table-scroll"><table class="extension-table"><caption class="sr-only"><?= e($t('nav.pages')) ?></caption>
<thead><tr><?php foreach (['name','description','status','actions'] as $column): ?><th scope="col"><?= e($t('catalog.'.$column)) ?></th><?php endforeach; ?></tr></thead>
<tbody><?php foreach ($rows as $slug=>$item): $data=$item['data']; $name=$item['title']; $protected=in_array((string)$slug,['home','404'],true); ?>
<tr data-page-id="<?= e($slug) ?>">
<td data-label="<?= e($t('catalog.name')) ?>"><strong class="page-depth-<?= $display==='tree'?$item['depth']:0 ?>"><?= e($name) ?></strong><small class="extension-id"><?= e($t('pages.model.'.$item['model'])) ?></small><small class="extension-id"><?= e($publicationReader->url((string)$slug,$context->base)) ?></small></td>
<td data-label="<?= e($t('catalog.description')) ?>"><?= e($data['meta']['description']) ?></td>
<td data-label="<?= e($t('catalog.status')) ?>"><span class="status <?= e($data['status']) ?>"><?= e($t('pages.state.'.$item['state'])) ?></span><small class="extension-id"><?= e($t('pages.updated').': '.($item['updated']?:$t('pages.unknownDate'))) ?></small><small class="extension-id"><?= e($t('pages.publishedAt').': '.($item['publishedAt']?:$t('pages.unknownDate'))) ?></small></td>
<td data-label="<?= e($t('catalog.actions')) ?>"><div class="row-actions">
<?php foreach (['preview','history','edit'] as $action): $label=$t('pages.'.$action.'_action',['name'=>$name]); ?>
<a class="icon-button" href="<?= e($action==='edit'&&$slug==='home'&&$homepageEnabled?$context->base.'/cms-admin/?view=plugin-panel&plugin=homepage&route=overview':$link($action==='edit'?'editor':$action,(string)$slug)) ?>" title="<?= e($label) ?>" aria-label="<?= e($label) ?>" <?= $action==='preview'?'target="_blank" rel="noopener"':'' ?>><?= Icons::svg($action,$context->base) ?></a>
<?php endforeach; ?>
<form method="post" action="<?= e($context->url($protected?'remove':'editorial-trash')) ?>" data-pages-form data-confirm="<?= e($t('editor.confirm_remove')) ?>">
<input type="hidden" name="catalog_revision" value="<?= e($catalog['revision']) ?>"><input type="hidden" name="site_revision" value="<?= e($siteRevision) ?>"><input type="hidden" name="source_revision" value="<?= e(isset($catalog['data']['records'][$slug])?'':$item['revision']) ?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="key" value="<?= e($slug) ?>"><input type="hidden" name="revision" value="<?= e($item['revision']) ?>"><input type="hidden" name="csrf_token" value="<?= e($csrf) ?>">
<button type="submit" class="icon-button danger" title="<?= e($protected?$t('pages.required'):$t('pages.remove_action',['name'=>$name])) ?>" aria-label="<?= e($t('pages.remove_action',['name'=>$name])) ?>" <?= $protected?'disabled':'' ?>><?= Icons::svg('uninstall',$context->base) ?></button>
</form></div></td></tr>
<?php endforeach; ?></tbody></table></div>
<div class="savebar"><?php if($catalogPage>1): ?><a class="icon-button" href="<?= e($pageLink($catalogPage-1)) ?>" title="<?= e($t('pages.previous')) ?>" aria-label="<?= e($t('pages.previous')) ?>"><?= Icons::svg('up',$context->base) ?></a><?php endif; ?><span><?= e($t('pages.pagination',['page'=>(string)$catalogPage,'pages'=>(string)$pageCount,'total'=>(string)$total])) ?></span><?php if($catalogPage<$pageCount): ?><a class="icon-button" href="<?= e($pageLink($catalogPage+1)) ?>" title="<?= e($t('pages.next')) ?>" aria-label="<?= e($t('pages.next')) ?>"><?= Icons::svg('arrow-right',$context->base) ?></a><?php endif; ?></div></section>
